6	const BONUS_TYPE_THRESHOLD = 3;
7	const POINTS_PER_BONUS_TYPE = 2;
8	
9	const isSphinx = (card: Card): boolean => card.monster === "sphinx";
10	
11	const countMonsterTypes = (army: Card[]): number =>
12	  new Set(army.map((card) => card.monster)).size;
13	
14	const scoreForOneSphinx = (monsterTypes: number): number =>
15	  monsterTypes > BONUS_TYPE_THRESHOLD
16	    ? 1 + POINTS_PER_BONUS_TYPE * (monsterTypes - BONUS_TYPE_THRESHOLD)
17	    : 2;
18	
19	export const scoreArmy = (army: Card[]): number =>
20	  army.reduce((score, card, index) => {
21	    if (!isSphinx(card)) return score;
22	    const otherCards = army.filter((_, other) => other !== index);
23	    return score + scoreForOneSphinx(countMonsterTypes(otherCards));
24	  }, 0);
